const { Given, When, Then, Before } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

let window;
let document;
let TodoApp;

// Load the app
Before(function () {
  window = new Window();
  document = window.document;
  // We'll load the app dynamically when needed
});

// Helper to load the app HTML
function loadApp() {
  const html = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>TodoMVC</title>
  </head>
  <body>
    <section class="todoapp">
      <header class="header">
        <h1>todos</h1>
        <input class="new-todo" placeholder="What needs to be done?" autofocus>
      </header>
      <section class="main">
        <input id="toggle-all" class="toggle-all" type="checkbox">
        <label for="toggle-all">Mark all as complete</label>
        <ul class="todo-list"></ul>
      </section>
      <footer class="footer">
        <span class="todo-count"><strong>0</strong> item left</span>
        <ul class="filters">
          <li>
            <a class="selected" href="#/">All</a>
          </li>
          <li>
            <a href="#/active">Active</a>
          </li>
          <li>
            <a href="#/completed">Completed</a>
          </li>
        </ul>
        <button class="clear-completed">Clear completed</button>
      </footer>
    </section>
  </body>
</html>`;
  document.write(html);

  // Load the app script
  const fs = require('fs');
  const path = require('path');
  const appCode = fs.readFileSync(path.join(__dirname, '../../js/app.js'), 'utf8');

  // Execute in the window context
  const script = document.createElement('script');
  script.textContent = appCode;
  document.head.appendChild(script);
}

// Helper to get todo elements
function getTodoElements() {
  return {
    newTodoInput: document.querySelector('.new-todo'),
    todoList: document.querySelector('.todo-list'),
    main: document.querySelector('.main'),
    footer: document.querySelector('.footer'),
    toggleAll: document.querySelector('#toggle-all'),
    todoCount: document.querySelector('.todo-count'),
    clearCompleted: document.querySelector('.clear-completed'),
    filters: {
      all: document.querySelector('a[href="#/"]'),
      active: document.querySelector('a[href="#/active"]'),
      completed: document.querySelector('a[href="#/completed"]')
    }
  };
}

// Helper to find a todo by title
function findTodoByTitle(title) {
  const todos = document.querySelectorAll('.todo-list li');
  for (const todo of todos) {
    const label = todo.querySelector('label');
    if (label && label.textContent === title) {
      return todo;
    }
  }
  return null;
}

// Given steps
Given('the app has no todos', function () {
  loadApp();
  const todos = getTodoElements();
  todos.todoList.innerHTML = '';
  localStorage.clear();
});

Given('the app has a todo {string}', function (title) {
  loadApp();
  const todos = getTodoElements();
  todos.todoList.innerHTML = '';

  const li = document.createElement('li');
  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox">
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;
  todos.todoList.appendChild(li);
});

Given('the app has todos {string} and {string}', function (title1, title2) {
  loadApp();
  const todos = getTodoElements();
  todos.todoList.innerHTML = '';

  [title1, title2].forEach(title => {
    const li = document.createElement('li');
    li.innerHTML = `
      <div class="view">
        <input class="toggle" type="checkbox">
        <label>${title}</label>
        <button class="destroy"></button>
      </div>
      <input class="edit" value="${title}">
    `;
    todos.todoList.appendChild(li);
  });
});

Given('both todos are active', function () {
  // Already active by default
});

Given('the app has {int} active todos', function (count) {
  loadApp();
  const todos = getTodoElements();
  todos.todoList.innerHTML = '';

  for (let i = 0; i < count; i++) {
    const li = document.createElement('li');
    li.innerHTML = `
      <div class="view">
        <input class="toggle" type="checkbox">
        <label>Todo ${i + 1}</label>
        <button class="destroy"></button>
      </div>
      <input class="edit" value="Todo ${i + 1}">
    `;
    todos.todoList.appendChild(li);
  }
});

Given('the app has one active todo {string}', function (title) {
  loadApp();
  const todos = getTodoElements();
  todos.todoList.innerHTML = '';

  const li = document.createElement('li');
  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox">
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;
  todos.todoList.appendChild(li);
});

Given('the app has completed todos {string} and {string}', function (title1, title2) {
  loadApp();
